 * Author: @sufyan-jutt (https://tailwindflex.com/@sufyan-jutt)
 * Source: https://tailwindflex.com/@sufyan-jutt/made-a-sinup-form
 * Attribution: Créé par @sufyan-jutt sur TailwindFlex
 * License: Open Source (TailwindFlex community)
 */
import React from "react";

export function MadeASinupForm() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>3D Signup Form</title>

  <style>
    body { perspective: 1500px; }

    .glow {
      position: relative;
      z-index: 1;
    }

    .glow::before {
      content: "";
      position: absolute;
      top: -50%;
      left: -50%;
      width: 200%;
      height: 200%;
      background: radial-gradient(circle, rgba(236,72,153,0.3), transparent 70%);
      filter: blur(60px);
      z-index: -1;
      transition: all 0.5s ease;
    }

    .card-inner {
      transform-style: preserve-3d;
      transition: transform 0.3s ease, box-shadow 0.3s ease;
    }
  </style>
</head>
<body class="bg-gradient-to-r from-purple-700 to-pink-600 flex items-center justify-center min-h-screen p-4">

  <div class="card glow w-full max-w-md rounded-3xl shadow-2xl overflow-hidden cursor-pointer card-inner">
    <div class="p-10 bg-white rounded-3xl">
      <h2 class="text-4xl font-bold text-gray-800 mb-8 text-center">Create Account</h2>
      <form class="space-y-6">

        <!-- Name Input -->
        <div class="relative">
          <input type="text" placeholder="Full Name" class="w-full px-12 py-4 rounded-xl border border-gray-300 focus:outline-none focus:ring-2 focus:ring-purple-400 focus:border-transparent transition"/>
          <!-- SVG User Icon -->
          <svg class="w-6 h-6 absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-400" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" d="M5.121 17.804A9 9 0 1118.879 6.196 9 9 0 015.121 17.804zM12 12a4 4 0 100-8 4 4 0 000 8z"/>
          </svg>
        </div>

        <!-- Email Input -->
        <div class="relative">
          <input type="email" placeholder="Email" class="w-full px-12 py-4 rounded-xl border border-gray-300 focus:outline-none focus:ring-2 focus:ring-pink-400 focus:border-transparent transition"/>
          <!-- SVG Mail Icon -->
          <svg class="w-6 h-6 absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-400" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" d="M16 12H8m0 0l4-4m0 0l4 4m-4-4v12"/>
          </svg>
        </div>

        <!-- Password Input -->
        <div class="relative">
          <input id="signupPassword" type="password" placeholder="Password" class="w-full px-12 py-4 rounded-xl border border-gray-300 focus:outline-none focus:ring-2 focus:ring-purple-400 focus:border-transparent transition"/>
          <!-- SVG Lock Icon -->
          <svg class="w-6 h-6 absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-400" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" d="M12 11c1.657 0 3 1.343 3 3v3H9v-3c0-1.657 1.343-3 3-3z"/>
            <path stroke-linecap="round" stroke-linejoin="round" d="M6 11V7a6 6 0 1112 0v4"/>
          </svg>
          <!-- Eye Icon -->
          <button type="button" id="toggleSignupPassword" class="absolute right-4 top-1/2 transform -translate-y-1/2 text-gray-400">
            <svg id="signupEyeOpen" class="w-6 h-6" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24">
              <path stroke-linecap="round" stroke-linejoin="round" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/>
              <path stroke-linecap="round" stroke-linejoin="round" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.477 0 8.268 2.943 9.542 7-1.274 4.057-5.065 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"/>
            </svg>
            <svg id="signupEyeClosed" class="w-6 h-6 hidden" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24">
              <path stroke-linecap="round" stroke-linejoin="round" d="M13.875 18.825A10.05 10.05 0 0112 19c-4.477 0-8.268-2.943-9.542-7a9.956 9.956 0 012.19-3.344m2.864-2.863A9.956 9.956 0 0112 5c4.477 0 8.268 2.943 9.542 7a10.05 10.05 0 01-1.11 2.158M3 3l18 18"/>
            </svg>
          </button>
        </div>

        <button type="submit" class="w-full py-4 rounded-xl bg-gradient-to-r from-purple-600 to-pink-500 text-white font-bold text-lg transition-transform duration-300 hover:scale-105 hover:shadow-xl">
          Sign Up
        </button>
      </form>
      <p class="text-center text-gray-500 mt-6 text-sm">Already have an account? <a href="#" class="text-purple-600 font-semibold hover:underline">Login</a></p>
    </div>
  </div>

  <!-- ===== JS for 3D Tilt & Eye Toggle ===== -->


</body>
</html>" }} />
  );
}
